27	@SpringBootTest
28	@AutoConfigureMockMvc
29	class PlanApiTest {
30	
31	    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
32	    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
33	
