     */
    public Optional<SectionBinding> findBinding(String sectionId) {
        return jdbc.query("SELECT id, section_id, substation_key, version FROM rail_section_binding"
                        + " WHERE section_id = ?",
                BINDING_MAPPER, sectionId).stream().findFirst();
